package main

// Target hosts live (agentry-desktop#812; plan runtime-hosts.md M6): the
// bound methods driven as the run setup drives them, against this
// machine's Docker and a throwaway SSH server, with a QuickAgent installed
// from a folder that asks for a server. Skipped unless AGENTRY_LIVE_HOSTS=1:
//
//	AGENTRY_LIVE_HOSTS=1 \
//	AGENTRY_CONFIG_DIR=<a scratch config dir> \
//	AGENTRY_RUNNER_HOME=<a scratch runner home> \
//	AGENTRY_LIVE_HOSTS_SERVER=<user>@<address>[:port]   (a throwaway sshd, never loopback) \
//	AGENTRY_LIVE_HOSTS_PASSWORD=<its password, generated by the caller> \
//	AGENTRY_LIVE_HOSTS_SUDO=<its sudo password, optional> \
//	AGENTRY_LIVE_HOSTS_OUT=<a folder to keep the runs' output in, optional> \
//	go test -run TestLiveTargetHost -v -timeout 60m .
//
// It refuses to run when the keychain already holds a sign-in for the
// server, so it never replaces or removes the person's own. With no model
// key on the machine a run stops once its containers are up; the host is
// readied before that (the dialog, the key, the sign-in), so the setup's
// half is checked either way, and with a model key the agent works the
// server and the receipt names it.
//
// What it holds: the first run puts the host key to the dialog with its
// type and SHA256 fingerprint, keeps it in the runner home's known_hosts,
// signs in with the password typed for it and saves it as the CLI's entry;
// the second asks nothing and signs in with the saved one; a key on file
// that differs from the server's refuses the third, naming both; the
// server is in the recent hosts; and no password is in any file a run left.

import (
	"bytes"
	"cmp"
	"context"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/zalando/go-keyring"

	"github.com/blaktron/agentry-cli/pkg/configdir"
	"github.com/blaktron/agentry-cli/pkg/runner/modelkey"
	"github.com/blaktron/agentry-cli/pkg/runner/policy"

	"github.com/blaktron/agentry-desktop/internal/run"
)

const liveHostsManifest = `schemaVersion: "2"
name: host-probe
namespace: local
modes: [autonomous]
version: 0.1.0
summary: "Names the server it is given (agentry-desktop#812 live check)"
entrypoints:
  instruction: SKILL.md
intake:
  - id: server
    prompt: "The server to look at"
    type: host
    required: true
capabilities:
  filesystem:
    read: workspace
    write: workspace
  targetHosts: [server]
publish:
  include: [agent.yaml, SKILL.md]
`

func TestLiveTargetHost(t *testing.T) {
	if os.Getenv("AGENTRY_LIVE_HOSTS") != "1" {
		t.Skip("reaches a server: set AGENTRY_LIVE_HOSTS=1 (see the file's comment)")
	}
	if os.Getenv(configdir.EnvVar) == "" || os.Getenv(policy.HomeEnv) == "" {
		t.Fatalf("set %s and %s to scratch directories", configdir.EnvVar, policy.HomeEnv)
	}
	server, password, sudo := os.Getenv("AGENTRY_LIVE_HOSTS_SERVER"), os.Getenv("AGENTRY_LIVE_HOSTS_PASSWORD"), os.Getenv("AGENTRY_LIVE_HOSTS_SUDO")
	if server == "" || password == "" {
		t.Fatal("set AGENTRY_LIVE_HOSTS_SERVER and AGENTRY_LIVE_HOSTS_PASSWORD")
	}
	outRoot := cmp.Or(os.Getenv("AGENTRY_LIVE_HOSTS_OUT"), t.TempDir())
	keychain := !modelkey.Disabled()

	var asked []string
	app := &App{ctx: context.Background(), confirm: func(_ context.Context, title, message string) (bool, error) {
		asked = append(asked, title+"\n"+message)
		return true, nil
	}}
	r := &RunAPI{app: app}
	b := &BuildAPI{app: app, run: r}

	st := r.TargetHostStatus(server)
	if st.Problem != "" {
		t.Fatalf("the server's address: %s", st.Problem)
	}
	if st.Saved {
		t.Fatalf("the keychain already holds a sign-in for %s: this test would replace it", st.Answer)
	}
	t.Cleanup(func() { _ = keyring.Delete(modelkey.Service, st.Account) })
	knownHosts := filepath.Join(os.Getenv(policy.HomeEnv), "known_hosts")

	dir := filepath.Join(outRoot, "probe")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	app.markPicked(dir)
	for name, body := range map[string]string{
		"agent.yaml": liveHostsManifest,
		"SKILL.md": "# Host probe\n\nWith host_run, run `hostname; id -un; uname -sr` on the server, then run `id -u` with sudo: true. " +
			"Report what each printed, in two lines. Finish in at most 4 tool calls.\n",
	} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := b.Install(dir); err != nil {
		t.Fatalf("install the probe: %v", err)
	}
	const ref = "local/host-probe@0.1.0"

	secrets := []string{password}
	if sudo != "" {
		secrets = append(secrets, sudo)
	}
	// noSecret fails when a password is in any file under the folders.
	noSecret := func(dirs ...string) {
		t.Helper()
		for _, d := range dirs {
			_ = filepath.WalkDir(d, func(p string, e fs.DirEntry, err error) error {
				if err != nil || e.IsDir() {
					return nil
				}
				raw, rerr := os.ReadFile(p)
				for _, s := range secrets {
					if rerr == nil && len(s) >= 8 && bytes.Contains(raw, []byte(s)) {
						t.Errorf("a password is in %s", p)
					}
				}
				return nil
			})
		}
	}
	// said is the run's receipts and intake.json under out.
	said := func(out string) string {
		var all strings.Builder
		_ = filepath.WalkDir(out, func(p string, e fs.DirEntry, err error) error {
			if err == nil && !e.IsDir() && (strings.HasSuffix(p, ".json") || strings.HasSuffix(p, ".log")) {
				raw, _ := os.ReadFile(p)
				all.Write(raw)
				all.WriteString("\n")
			}
			return nil
		})
		return all.String()
	}
	runIt := func(name string, given map[string]run.HostSignIn) (string, *RunResultView, error) {
		out := filepath.Join(outRoot, name)
		if err := os.MkdirAll(out, 0o755); err != nil {
			t.Fatal(err)
		}
		app.markPicked(out)
		asked = nil
		res, err := r.RunAgent("https://secureagentry.net", ref, "", nil, out, nil, 0, -1, true, map[string]string{"server": server}, false, false, nil, false, nil, given)
		if res != nil {
			t.Logf("%s: status %s, exit %d, %s", name, res.Status, res.ExitCode, res.Error)
		}
		if err != nil {
			t.Logf("%s: the run ended with %v", name, err)
		}
		return out, res, err
	}
	hostKeyAsks := func() (n int, last string) {
		for _, a := range asked {
			if strings.HasPrefix(a, "Accept this host key?") {
				n, last = n+1, a
			}
		}
		return n, last
	}

	// 1. A key on no file goes to the dialog; the typed password signs in
	// and is saved as the CLI's entry; the key is kept.
	out, res, err := runIt("typed", map[string]run.HostSignIn{"server": {Password: password, Sudo: sudo, Save: keychain}})
	if n, prompt := hostKeyAsks(); n != 1 || !strings.Contains(prompt, "SHA256:") {
		t.Fatalf("typed: the host key dialog was asked %d times (%q)", n, prompt)
	} else {
		t.Logf("typed: the dialog said: %s", prompt)
	}
	if raw, rerr := os.ReadFile(knownHosts); rerr != nil || len(raw) == 0 {
		t.Fatalf("typed: the runner home's known_hosts: %v", rerr)
	}
	if err != nil && res == nil && strings.Contains(err.Error(), "host-refused") {
		t.Fatalf("typed: refused: %v", err)
	}
	text := said(out)
	if strings.Contains(text, "host link") {
		t.Logf("typed: the receipt names the host link")
	}
	noSecret(out)
	if keychain {
		if v := r.TargetHostStatus(server); !v.Saved {
			t.Errorf("typed: the sign-in was not saved")
		}
	}
	if rh := r.RecentHosts(); len(rh) == 0 || rh[0] != st.Answer {
		t.Errorf("typed: recent hosts %q", rh)
	}

	// 2. Nothing typed: the saved sign-in, and no dialog.
	if keychain {
		out, _, _ = runIt("saved", nil)
		if n, _ := hostKeyAsks(); n != 0 {
			t.Errorf("saved: the dialog was asked again")
		}
		if strings.Contains(said(out), "typed at the run's start") {
			t.Errorf("saved: the receipt says the sign-in was typed")
		}
		noSecret(out)
	}

	// 3. A key on file that is not the server's refuses the run, naming
	// both, and asks nothing.
	raw, _ := os.ReadFile(knownHosts)
	t.Cleanup(func() { _ = os.WriteFile(knownHosts, raw, 0o600) })
	wrong := "AAAAC3NzaC1lZDI1NTE5AAAAIOwaZ1Hx9P9b9xg0n9XQe2zYw2gq3wq9h3d8y4p0QmXo"
	lines := strings.Fields(strings.TrimSpace(string(raw)))
	if len(lines) < 3 {
		t.Fatalf("the runner's known_hosts %q", raw)
	}
	if err := os.WriteFile(knownHosts, []byte(lines[0]+" ssh-ed25519 "+wrong+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	_, _, err = runIt("changed", map[string]run.HostSignIn{"server": {Password: password}})
	if err == nil || !strings.Contains(err.Error(), "has changed") {
		t.Fatalf("changed: %v", err)
	}
	if n, _ := hostKeyAsks(); n != 0 {
		t.Errorf("changed: the dialog was asked")
	}
	t.Logf("changed: %v", err)

	noSecret(os.Getenv(policy.HomeEnv), os.Getenv(configdir.EnvVar))
}
